     <script>
         const queryInput = document.getElementById('queryinput');
         const startButton = document.getElementById('startbutton');
         const outputContainer = document.getElementById('outputcontainer');
         let ws;

         function connectWebSocket() {
             const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
             const host = window.location.host;
             ws = new WebSocket(${proto}//${host}/ws);

             ws.onopen = () => {
                 appendMessage('log', 'Sikeres kapcsolat az ágens magjával.');
                 startButton.disabled = false;
             };

             ws.onmessage = (event) => {
                 const data = JSON.parse(event.data);
                 handleMessage(data);
             };

             ws.onclose = () => {
                 appendMessage('error', 'A kapcsolat megszakadt. Újracsatlakozási kísérlet 5 másodperc múlva...');
                 startButton.disabled = true;
                 setTimeout(connectWebSocket, 5000);
             };

             ws.onerror = (error) => {
                 console.error('WebSocket hiba:', error);
                 appendMessage('error', 'WebSocket kommunikációs hiba történt.');
             };
         }

         function startInvestigation() {
             const query = queryInput.value.trim();
             if (!query) {
                 alert('Kérem, adja meg a nyomozás tárgyát!');
                 return;
             }
             if (ws && ws.readyState === WebSocket.OPEN) {
                 outputContainer.innerHTML = '';
                 appendMessage('log', Nyomozás indítva a következő témában: "${query}");
                 ws.send(JSON.stringify({ query: query }));
                 startButton.disabled = true;
                 queryInput.disabled = true;
             } else {
                 appendMessage('error', 'Nincs aktív kapcsolat az ágenssel. Próbálja meg frissíteni az oldalt.');
             }
         }

         function handleMessage(data) {
             const { type, content } = data;
             switch(type) {
                 case 'log':
                 case 'thinking':
                 case 'action':
                 case 'error':
                     appendMessage(type, content);
                     break;
                 case 'hypotheses':
                     let hypothesesHtml = '<h3>Frissített Hipotézisek:</h3><ul>';
                     content.forEach(h => {
                         hypothesesHtml += <li>${h}</li>;
                     });
                     hypothesesHtml += '</ul>';
                     appendMessage(type, hypothesesHtml, true);
                     break;
                 case 'discoveries':
                     let discoveriesHtml = '<h3>Új Felfedezések:</h3><ul>';
                     content.forEach(d => {
                         discoveriesHtml += <li><strong>Entitás:</strong> ${d.entity}<br><strong>Állítás:</strong> ${d.claim}<br><em>Forrás: ${d.source || 'Ismeretlen'}</em></li>;
                     });
                     discoveriesHtml += '</ul>';
                     appendMessage(type, discoveriesHtml, true);
                     break;
                 case 'graph_update':
                      let graphHtml = <h3>Tudásgráf Frissítés:</h3><div class="graph"><img src="${content}" alt="Tudásgráf vizualizáció"></div>;
                     appendMessage('graph', graphHtml, true);
                     break;
                 case 'final_report':
                     const reportHtml = marked.parse(content);
                     appendMessage(type, <h2>Végső Nyomozati Jelentés</h2>${reportHtml}, true);
                     startButton.disabled = false;
                     queryInput.disabled = false;
                     break;
                 default:
                     appendMessage('log', Ismeretlen üzenettípus: ${type});
             }
         }

         function appendMessage(type, content, isHtml = false) {
             const messageDiv = document.createElement('div');
             messageDiv.className = message ${type};
             if (isHtml) {
                 messageDiv.innerHTML = content;
             } else {
                 messageDiv.textContent = content;
