 @app.websocket("/ws")
 async def websocket_endpoint(websocket: WebSocket):
     """Kezeli a WebSocket kapcsolatot és a nyomozási folyamatot."""
     await websocket.accept()
     try:
         while True:
             data = await websocket.receive_json()
             query = data.get("query")
             if query:
                 investigator = AutonomousInvestigator(websocket)
